}

Method.Source:
public void new(IdentifierName              _className      = classStr(AVAAutoPrintBillOfLadingService),
                IdentifierName              _methodName     =  methodStr(AVAAutoPrintBillOfLadingService, autoPrint),
                SysOperationExecutionMode   _executionMode  = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

public static AVAAutoPrintBillOfLadingController construct(SysOperationExecutionMode _mode = SysOperationExecutionMode::Synchronous)
{
    AVAAutoPrintBillOfLadingController controller = new AVAAutoPrintBillOfLadingController(classStr(AVAAutoPrintBillOfLadingService),
                                                                                           methodStr(AVAAutoPrintBillOfLadingService, autoPrint),
                                                                                           _mode);
    return controller;
}

private static void main(Args _args)
{
    AVAAutoPrintBillOfLadingController controller;
    controller = AVAAutoPrintBillOfLadingController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}
